const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.file}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
/* 搜索命中高亮：与列表过滤同款的忽略大小写子串匹配，在原文上定位、分段转义后包 mark */
const markHits=(text,q)=>{
 if(!q)return esc(text);
 const hay=text.toLowerCase(),needle=q.toLowerCase();
 let out='',last=0,hit=hay.indexOf(needle);
 while(hit>=0){
  out+=esc(text.slice(last,hit))+'<mark>'+esc(text.slice(hit,hit+needle.length))+'</mark>';
  last=hit+needle.length;
  hit=hay.indexOf(needle,last);
 }
 return out+esc(text.slice(last));
};
const localDate=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const today=localDate();let page='home',filter='all',query='',selectedDate='',month=new Date().getMonth(),year=new Date().getFullYear(),detailTab='notes',currentId=null;
let records=[],appState={settings:{},watch:{}},connectionError='';
const deleting=new Set(),deleteTimers=new Map(),DELETE_DELAY=6000;
const cat=id=>categories.find(c=>c.id===id)||categories.find(c=>c.id==='inbox')||categories[0];
const catStyle=c=>`color:${/^#[a-f0-9]{6}$/i.test(c.color)?c.color:'#607646'};background:${/^#[a-f0-9]{6}$/i.test(c.color)?c.color:'#607646'}15`;
const categoryTag=id=>{const c=cat(id);return `<span class="tag" style="${catStyle(c)}">${esc(c.name)}</span>`};
const names={home:'我的工作台',all:'全部记录',timeline:'每日足迹',review:'复盘与学习',favorites:'我的收藏',queue:'处理队列',connections:'应用关联',devices:'设备连接',ask:'问录音',recaps:'回顾档案'};
const deviceConnections=createDeviceConnections({api,toast});
/* 外观主题：跟随系统（默认）/ 浅色 / 深色，记忆在 localStorage，切换即时生效 */
const THEME_KEY='shengji.theme';
const systemDark=matchMedia('(prefers-color-scheme: dark)');
const THEME_META={auto:['monitor','跟随系统'],light:['sun','浅色'],dark:['moon','深色']};
let themeMode='auto';try{themeMode=localStorage.getItem(THEME_KEY)||'auto'}catch{}
if(!['auto','light','dark'].includes(themeMode))themeMode='auto';
function applyTheme(){const resolved=themeMode==='auto'?(systemDark.matches?'dark':'light'):themeMode;document.documentElement.dataset.theme=resolved;document.querySelectorAll('meta[name="theme-color"]').forEach(m=>{m.removeAttribute('media');m.setAttribute('content',resolved==='dark'?'#131019':'#f4f3f8')})}
systemDark.addEventListener('change',()=>{if(themeMode==='auto')applyTheme()});
applyTheme();
const themeIcon=()=>THEME_META[themeMode][0],themeLabel=()=>THEME_META[themeMode][1];
function cycleTheme(){themeMode=themeMode==='auto'?'light':themeMode==='light'?'dark':'auto';try{localStorage.setItem(THEME_KEY,themeMode)}catch{}applyTheme();render();toast(`外观已切换：${themeLabel()}`)}
function toast(message,action,ms=3500){const t=document.querySelector('#toast');clearTimeout(window.toastTimer);if(action){t.innerHTML=`${esc(message)}<button type="button" class="toast-action">${esc(action.label)}</button>`;t.querySelector('.toast-action').onclick=()=>{clearTimeout(window.toastTimer);t.classList.remove('show');action.run()}}else t.textContent=message;t.classList.add('show');window.toastTimer=setTimeout(()=>t.classList.remove('show'),ms)}
function refresh(){records=getRecords().filter(r=>!deleting.has(r.id));appState=getState();render()}
function cancelDelete(id){clearTimeout(deleteTimers.get(id));deleteTimers.delete(id);deleting.delete(id);refresh();toast('已撤销删除')}
function navButton(id,label,i,count,color=''){return `<button class="nav-item ${page===id?'active':''}" data-page="${id}" title="${esc(label)}">${icon(i)}<span ${color?`style="color:${color}"`:""}>${esc(label)}</span>${count!==undefined?`<span class="count">${count}</span>`:''}</button>`}
function render(){const real=records.filter(r=>!r.demo);document.querySelector('#app').innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-icon">${icon('mic')}</div><div><div class="brand-name">声迹</div><div class="brand-sub">录音豆的智能转写助手</div></div></div><div class="nav-label">我的空间</div><nav>${navButton('home','我的工作台','grid')}${navButton('all','全部记录','folder',records.length)}${navButton('timeline','每日足迹','clock')}${navButton('review','复盘与学习','book')}${navButton('recaps','回顾档案','calendar')}${navButton('favorites','我的收藏','star')}${navButton('queue','处理队列','list')}${navButton('ask','问录音','spark')}${navButton('devices','设备连接','headphones')}${navButton('connections','应用关联','link')}</nav><div class="nav-label category-heading">场景分类<button class="icon-btn" data-action="categories" aria-label="管理分类">${icon("plus")}</button></div><nav class="category-nav">${categories.map(c=>navButton(c.id,c.name,c.icon,records.filter(r=>r.category===c.id).length,c.color)).join('')}</nav><button class="text-btn category-manage" data-action="categories">${icon("folder")} 管理分类 / 添加分类</button><div class="sidebar-bottom"><div class="storage-card"><div>${icon('mic')} <strong>你的声音，有迹可循</strong></div><p>从一次记录开始，<br>慢慢积累自己的第二大脑。</p><span class="local-indicator">● 原文与记录保存在本机</span></div><button class="nav-item" data-action="theme">${icon(themeIcon())}<span>外观：${themeLabel()}</span></button><button class="nav-item" data-action="automation">${icon('spark')}<span>自动整理设置</span></button><button class="nav-item" data-action="backup">${icon('download')}<span>数据备份与恢复</span></button><div class="sidebar-signature">SHENGJI · PERSONAL MEMORY</div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumbs">我的空间 <span>/</span> <strong>${esc(names[page]||cat(page).name)}</strong></div><div class="top-actions"><button class="btn btn-secondary palette-open" data-action="palette">${icon('search')}快速查找</button><button class="icon-btn" data-action="automation" aria-label="自动整理设置">${icon('spark')}</button><button class="icon-btn" data-action="backup" aria-label="数据备份与恢复">${icon('download')}</button><button class="icon-btn" data-action="theme" aria-label="切换外观，当前${themeLabel()}" title="外观：${themeLabel()}">${icon(themeIcon())}</button><span class="top-date">${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}</span><span class="avatar">我</span></div></header><main class="main${takeReveal()?' optical-reveal':''}" id="main"><div class="page-heading"><div><div class="eyebrow">A LITTLE EVERY DAY</div><h1>${page==='home'?'录音放进来，思路留下来':esc(names[page]||cat(page).name)}</h1><p>${page==='home'?'拖入录音，自动转写、去口水词和生成摘要。':page==='review'?'从说过的话里，找到下一次进步的起点。':'让每一段声音，都回到它所属的时刻。'}</p></div><button class="btn btn-primary" data-action="import">${icon('plus')}导入录音 / 文字</button></div>${records.some(r=>r.demo)?`<div class="demo-banner">${icon('spark')} 当前包含演示记录，帮助你了解整理方式。你的真实记录有 ${real.length} 条。<button data-action="clear-demo">移除演示</button></div>`:''}${connectionError?`<div class="connection-error" role="alert">${esc(connectionError)}</div>`:''}${page==='home'?automationStrip()+reviewReminder()+gemFlash()+digestCard()+weeklyCard()+monthlyCard()+yearlyCard()+dashboard():contentPage()}</main><footer class="page-footer">每一段声音，都是你认真生活的回响。<span>声迹 · 你的录音第二大脑</span></footer><button type="button" class="icon-btn" id="scroll-top" aria-label="回到顶部">${icon('arrowUp')}</button></div></div>`;bind();animateStats()}
function dashboard(){let pending=records.filter(r=>!r.reviewed).length;return `<div class="dashboard-grid"><div class="primary-column"><section class="hero"><div class="hero-copy"><div class="hero-kicker"><span></span> RECORD. REFLECT. GROW.</div><h2>从一段录音，<br>到一份清楚的记录</h2><p>MP3 / M4A / WAV 直接拖进工作台。<br>原文完整保留，整理稿与摘要一起回看。</p><div class="hero-actions"><button class="btn btn-primary" data-action="import">${icon('upload')}导入一段记录</button><span>MP3 · M4A · WAV / TXT · MD · SRT · VTT</span></div></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="bean"><div class="bean-light"></div><div class="bean-slot"></div><div class="bean-mark">声迹</div></div><div class="sound-bars">${[12,23,38,54,30,43,64,42,25,39,19,10].map(h=>`<i style="height:${h}px"></i>`).join('')}</div><span class="art-note">每一个当下，都值得被记住</span></div></section><section class="stats-grid">${stat('mic','已留住的记录',records.length,'段声音，组成生活的拼图','all')}${stat('clock','记录过的日子',new Set(records.map(r=>r.date)).size,'天，让记忆不再模糊','timeline')}${stat('book','等待回看的记录',pending,'段对话，值得再听见','review')}</section><div class="section-head"><h2>最近的声音 <span>RECENT MEMORIES</span></h2><button class="text-btn" data-page="all">查看全部 ${icon('arrow')}</button></div>${filters()}<div class="record-list">${(query?listRecords():listRecords().slice(0,5)).map(recordCard).join('')||empty()}</div></div><aside class="right-column">${calendar()}<section class="panel review-progress"><div class="section-head"><h3>给成长一点回响</h3>${icon('book')}</div><p>记录之后，再向前走一步。</p><div class="review-number"><strong>${records.filter(r=>r.reviewed).length}</strong><span> / ${records.length} 段已复盘</span></div><div class="progress-track"><div class="progress-fill" style="width:${records.length?records.filter(r=>r.reviewed).length/records.length*100:0}%"></div></div><button class="btn btn-secondary" data-page="review">开始今日复盘 ${icon('arrow')}</button></section><section class="insight-card"><div class="insight-icon">✳</div><div class="eyebrow">给未来的自己</div><blockquote>记录的意义，<br>是让经历不止于经历。</blockquote><p>有些答案，藏在你说过的话里。</p><div class="insight-line"></div></section></aside></div>`}
const showMoreBtn=n=>`<button type="button" class="btn btn-secondary show-more" data-show-more>显示更多（还有 ${n} 条）</button>`;
function stat(i,label,val,note,go){return `<button type="button" class="stat-card"${go?` data-stat-page="${go}" title="查看${label}"`:''}><div class="stat-icon ${i}">${icon(i)}</div><div class="stat-label">${label}</div><div class="stat-value">${val.toString().padStart(2,'0')}</div><div class="stat-note">${note}</div></button>`}
function filters(){return `<div class="filter-row"><div class="chips">${(categories.some(c=>c.id===page)?[]:[{id:'all',name:'全部'},...categories]).map(c=>`<button class="chip ${filter===c.id?'active':''}" data-filter="${c.id}">${esc(c.name)}</button>`).join('')}${selectedDate?`<button class="chip active" data-clear-date>${esc(selectedDate)} ${icon('close')}</button>`:''}</div><label class="search-box">${icon('search')}<input id="search" aria-label="搜索记录" placeholder="搜索声音里的记忆（⌘K 或 / ）" title="按 ⌘K 或 / 快速聚焦" value="${esc(query)}"><span class="search-kbd" aria-hidden="true"><kbd>⌘K</kbd></span>${query?`<button type="button" class="icon-btn search-clear" data-clear-search aria-label="清除搜索">${icon('close')}</button>`:''}</label></div>`}
function listRecords(){return records.filter(r=>(!categories.some(c=>c.id===page)||r.category===page)&&(page!=='favorites'||r.favorite)&&(categories.some(c=>c.id===page)||filter==='all'||r.category===filter)&&(!selectedDate||r.date===selectedDate)&&(!query||[r.title,r.transcript,r.cleanedTranscript||'',r.summary,...r.highlights,...r.learnings,...r.actions].join(' ').toLowerCase().includes(query.toLowerCase()))).sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time))}
const daysAgo=d=>Math.round((new Date(today+'T00:00:00')-new Date(d+'T00:00:00'))/864e5);
const dateLabel=d=>d===today?'今天':daysAgo(d)===1?'昨天':daysAgo(d)>1&&daysAgo(d)<=7?`${daysAgo(d)} 天前`:esc(d.slice(5).replace('-','月')+'日');
const resultCount=(n,suffix='段记录')=>query?`找到 ${n} 条「${esc(query)}」`:`${n} ${suffix}`;
function recordCard(r){const c=cat(r.category);return `<article class="record-card ${r.value==='gem'?'gem':''}"><button class="record-main" data-open="${esc(r.id)}"><div class="record-icon" style="${catStyle(c)}">${icon(c.icon)}</div><div class="record-body"><div class="record-meta">${dateLabel(r.date)} <span>·</span> ${esc(r.time)} <span>·</span> ${r.duration?`${r.duration} 分钟`:'时长未填写'}${r.demo?' <span>·</span> 演示':''}${r.source?.kind==='watch'?' <span>·</span> 自动导入':r.source?.kind==='connector'?' <span>·</span> 设备同步':''}${r.value==='gem'?` <span class="gem-tag">${icon('star')} 干货</span>${(r.gemTags||[]).slice(0,2).map(t=>` <span class="gem-mini-tag">${esc(t)}</span>`).join('')}`:''}${r.reviewCount>0?` <span class="review-count">复看 ${r.reviewCount} 次</span>`:''}</div><h3 class="record-title">${markHits(r.title,query)}</h3><p class="record-excerpt">${markHits(r.summary||r.transcript.slice(0,100),query)}</p><div class="record-tags">${transcriptionBadge(r)}${aiBadge(r)}${categoryTag(r.category)}<span class="status-tag ${r.reviewed?'done':''}">${r.reviewed?'✓ 已复盘':'○ 待复盘'}</span>${r.highlights.length?`<span class="snippet-tag">${r.highlights.length} 个关键片段</span>`:''}</div></div></button><div class="record-tail"><button class="icon-btn ${r.favorite?'is-favorite':''}" data-favorite="${esc(r.id)}" aria-label="${r.favorite?'取消收藏':'收藏'} ${esc(r.title)}">${icon('star')}</button><button class="icon-btn" data-open="${esc(r.id)}" aria-label="打开 ${esc(r.title)}">${icon('chevron')}</button></div></article>`}
function empty(){if(query)return `<div class="empty-state">${icon('mic')}<div class="empty-wave" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div><h3>没有找到与「${esc(query)}」相关的记录</h3><p>换个关键词，或清除搜索看看全部。</p><button class="btn btn-secondary" data-clear-search>清除搜索</button>${selectedDate?`<button class="btn btn-secondary" data-clear-date>清除日期筛选</button>`:''}<button class="btn btn-secondary" data-action="import">导入录音 / 文字</button></div>`;if(selectedDate)return `<div class="empty-state">${icon('mic')}<div class="empty-wave" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div><h3>这一天还没有留下声音</h3><p>看看其他日期，或回到全部记录。</p><button class="btn btn-secondary" data-clear-date>查看全部</button></div>`;return `<div class="empty-state">${icon('mic')}<div class="empty-wave" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div><h3>这里还没有留下声音</h3><p>导入一段录音或文字，或调整筛选条件。</p><button class="btn btn-secondary" data-page="all">查看全部记录</button><button class="btn btn-secondary" data-action="import">导入录音 / 文字</button></div>`}
