document.querySelectorAll('[data-recap-export]').forEach(b=>b.onclick=()=>{const [type,key]=b.dataset.recapExport.split(':');const e=recapEntries().find(x=>x.type===type&&x.key===key);if(!e)return;download(recapFilename(e),recapMarkdown(e),'text/markdown')});
document.querySelectorAll('[data-recap-export-all]').forEach(b=>b.onclick=()=>{const all=recapEntries();if(!all.length)return toast('还没有可导出的回顾');download(`声迹回顾档案-${today}.md`,all.map(e=>recapMarkdown(e)).join('\n\n---\n\n'),'text/markdown')});document.querySelectorAll('[data-export-gems]').forEach(b=>b.onclick=()=>{const gems=listRecords().filter(r=>r.value==='gem'&&(!gemTagFilter||(r.gemTags||[]).includes(gemTagFilter))).sort((a,b)=>String(a.lastReviewedAt||'').localeCompare(String(b.lastReviewedAt||''))||String(b.date).localeCompare(String(a.date)));if(!gems.length)return toast('当前筛选下没有可导出的干货');download(`声迹干货合集-${today}.md`,`# 干货合集 · ${gems.length} 条\n\n${gems.map(g=>recordMarkdown(g,cat(g.category).name)).join('\n\n---\n\n')}\n`,'text/markdown')});document.querySelectorAll('[data-gem-filter]').forEach(b=>b.onclick=()=>{gemTagFilter=b.dataset.gemFilter;refresh()});document.querySelectorAll('[data-flash-another]').forEach(b=>b.onclick=()=>{const gems=records.filter(r=>r.value==='gem');if(!gems.length)return;const pool=gems.length>1?gems.filter(g=>g.id!==flashGemId):gems,g=pool[Math.floor(Math.random()*pool.length)];flashGemId=g.id;flashAt=Date.now();refresh()});
const scrollBtn=document.querySelector('#scroll-top');if(scrollBtn){scrollBtn.classList.toggle('show',window.scrollY>420);scrollBtn.onclick=()=>window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}
