/* 统计数字滚动：仅跟随点击触发的 optical-reveal 渲染播放，后台轮询刷新时保持静止 */
function animateStats(){const mainEl=document.querySelector('main.main');if(!mainEl||!mainEl.classList.contains('optical-reveal'))return;if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;mainEl.querySelectorAll('.stat-value').forEach((el,i)=>{const target=Number(el.textContent)||0;if(!target)return;const begin=performance.now()+90+i*70,dur=620;const step=t=>{const p=Math.min(1,Math.max(0,(t-begin)/dur)),ease=1-(1-p)**3;el.textContent=String(Math.round(target*ease)).padStart(2,'0');if(p<1)requestAnimationFrame(step)};requestAnimationFrame(step)})}
window.addEventListener('scroll',()=>{const b=document.querySelector('#scroll-top');if(b)b.classList.toggle('show',window.scrollY>420)},{passive:true});
