function scheduleDetailDraftCapture(){clearTimeout(draftCaptureTimer);draftCaptureTimer=setTimeout(captureDetailDraft,300)}
window.addEventListener('pagehide',()=>{clearTimeout(draftCaptureTimer);captureDetailDraft()});
function restoreDetailDraft(id){
 const draft=detailDrafts.get(id);
 if(!draft)return false;
 for(const f of draft.fields){const el=document.getElementById(f.id);if(el){el.value=f.value;if(el.type==='checkbox')el.checked=f.checked}}
 dirty=true;
 toast('已恢复这条记录的未保存草稿');
 return true;
}
function closeModal(){if(savingDetailForm){toast('正在保存整理，请稍候');return}if(importBusy){toast('正在保存导入队列，请稍候');return}clearTimeout(draftCaptureTimer);captureDetailDraft();if(!modal.querySelector('#detail-form')&&tabDraft&&currentId){detailDrafts.set(currentId,{fields:tabDraft});persistDrafts()}dirty=false;modal.close()}
modal.addEventListener('cancel',e=>{e.preventDefault();closeModal()});
modal.addEventListener('keydown',e=>{if(!modal.open)return;if(e.target.closest?.('input,textarea,select,[contenteditable]'))return;if(e.key===' '&&(!e.target.closest?.('button,[role="button"],a')||e.target.closest?.('.detail-nav button'))){const playButton=modal.querySelector('#audio-play');if(playButton){e.preventDefault();playButton.click()}return}const prev=modal.querySelector('[data-nav-record][aria-label="上一条记录"]:not([disabled])'),next=modal.querySelector('[data-nav-record][aria-label="下一条记录"]:not([disabled])');if(e.key==='ArrowLeft'&&prev){e.preventDefault();prev.click()}else if(e.key==='ArrowRight'&&next){e.preventDefault();next.click()}});
function showModal(html){hideMiniPlayer();modal.innerHTML=html;modal.classList.remove('optical-reveal');void modal.offsetWidth;if(takeReveal())modal.classList.add('optical-reveal');dirty=false;modal.oninput=e=>{if(e.target.closest?.('.audio-player'))return;dirty=true;scheduleDetailDraftCapture()};modal.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal);if(!modal.open)modal.showModal()}
const closeButton=`<button class="icon-btn" data-close aria-label="关闭">${icon('close')}</button>`;
let importQueue=[];
const audioFile=f=>/\.(mp3|m4a|wav)$/i.test(f.name);
const textFile=f=>/\.(txt|md|srt|vtt)$/i.test(f.name);
const fileBase64=file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(new Error('文件读取失败'));reader.readAsDataURL(file)});
function importPending(){return importQueue.some(x=>x.status!=='done')||!!document.querySelector('#transcript-input')?.value.trim()}
function hasPairedImportAudio(){const pending=importQueue.filter(x=>x.status!=='done');return pending.length===1&&audioFile(pending[0].file)}
function drawImportQueue(){const el=document.querySelector('#import-queue');if(!el)return;el.innerHTML=importQueue.map((x,i)=>`<div class="import-queue-row ${x.status}"><div>${icon(audioFile(x.file)?'mic':'file')}<strong>${esc(x.file.name)}</strong><small>${(x.file.size/1024/1024).toFixed(2)} MB · ${esc(({pending:'等待导入',running:'正在保存',done:'已保存',failed:'导入失败'})[x.status])}</small>${x.error?`<p role="alert">${esc(x.error)}</p>`:''}</div>${x.id?`<button type="button" class="text-btn" data-import-open="${esc(x.id)}">查看</button>`:''}<button type="button" class="icon-btn" data-remove-file="${i}" aria-label="移除 ${esc(x.file.name)}" ${importBusy?'disabled':''}>${icon('close')}</button></div>`).join('');el.querySelectorAll('[data-remove-file]').forEach(b=>b.onclick=()=>{importQueue.splice(Number(b.dataset.removeFile),1);dirty=importPending();drawImportQueue()});el.querySelectorAll('[data-import-open]').forEach(b=>b.onclick=()=>{if(importBusy)return;openDetail(b.dataset.importOpen)});const button=document.querySelector('#import-submit');if(button){button.disabled=importBusy;button.textContent=importBusy?'正在依次保存…':importQueue.some(x=>x.status==='failed')?'重试未成功的文件':'保存并开始处理'}const hint=document.querySelector('#pairing-note');if(hint)hint.textContent=hasPairedImportAudio()?'下方文字会作为这段录音的配套文字稿，跳过自动语音转写。':'批量文件各自保存为独立记录；下方另行粘贴的文字会单独保存。'}
/* 读音频元数据估算时长（分钟）：拖入即预填，省去手动查时长 */
const readAudioMinutes=file=>new Promise(resolve=>{const url=URL.createObjectURL(file),probe=new Audio();probe.preload='metadata';const done=v=>{probe.onloadedmetadata=probe.onerror=null;URL.revokeObjectURL(url);resolve(v)};probe.onloadedmetadata=()=>done(Number.isFinite(probe.duration)&&probe.duration>0?Math.round(probe.duration/60):null);probe.onerror=()=>done(null);probe.src=url});
function addImportFiles(files){let added=false;for(const file of Array.from(files)){let error='';if(!audioFile(file)&&!textFile(file))error='不支持此格式，请使用 MP3、M4A、WAV 或 TXT、MD、SRT、VTT';else if(file.size>(audioFile(file)?100:5)*1024*1024)error=`文件过大：${audioFile(file)?'音频最多 100 MB':'文字最多 5 MB'}`;else if(!file.size)error='文件为空';const item={file,status:error?'failed':'pending',error};importQueue.push(item);if(!error){added=true;if(audioFile(file))readAudioMinutes(file).then(d=>{if(d===null||!importQueue.includes(item))return;item.duration=d;if(importQueue.length===1){const el=document.querySelector('#duration-input');if(el&&!el.value)el.value=d}drawImportQueue()})}}if(added)dirty=true;drawImportQueue()}
function openImport(files=[],pasted=''){
 if(savingDetailForm){toast('正在保存整理，请稍候');return false}
 if(importBusy){toast('正在保存队列，请稍候');return false}
 captureDetailDraft();
 importQueue=[];
 showModal(`<div class="modal-head"><div><div class="eyebrow">CAPTURE A MOMENT</div><h2>导入录音与文字</h2><p>录音先转成文字，再整理；已有文字稿可以直接导入。</p></div>${closeButton}</div><form id="import-form"><div class="modal-body"><label class="dropzone" id="dropzone" tabindex="0" role="button" aria-label="选择录音或文字文件">${icon('upload')}<strong>选择多个文件，或拖到窗口任意位置</strong><span>MP3 / M4A / WAV：每个最多 100 MB<br>TXT / MD / SRT / VTT：每个最多 5 MB</span><input id="file-input" type="file" accept=".mp3,.m4a,.wav,.txt,.md,.srt,.vtt" multiple hidden></label><div id="import-queue" aria-live="polite"></div><p class="form-note" id="pairing-note">批量文件各自保存为独立记录。</p><div class="field"><label for="transcript-input">粘贴文字稿 <span>可选</span></label><textarea id="transcript-input" rows="5" maxlength="500000" placeholder="直接粘贴转写原文；只选一个音频时，会作为该音频的配套稿。">${esc(pasted)}</textarea></div><label class="check-label ai-toggle"><input type="checkbox" id="auto-analyze" ${appState.settings.autoAnalyze!==false?'checked':''}>有文字后自动整理 · 本地 Qwen</label><div class="form-grid"><div class="field"><label for="title-input">标题 <span>可留空，批量时使用各文件名</span></label><input id="title-input" maxlength="120" placeholder="不必为每一段录音手动命名"></div><div class="field"><label for="category-input">初始分类</label><select id="category-input">${[...categories].sort((a,b)=>a.id==='inbox'?-1:b.id==='inbox'?1:0).map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label for="date-input">录音日期</label><input id="date-input" type="date" value="${today}" required></div><div class="field"><label for="time-input">录音时间</label><input id="time-input" type="time" value="${new Date().toTimeString().slice(0,5)}" required></div><div class="field"><label for="duration-input">时长（分钟，可选）</label><input id="duration-input" type="number" min="0" max="10000" step="1"></div></div><p class="form-note">保存音频后可以随时回放。语音转写或 AI 整理失败会保留记录，可重试或补贴文字稿。</p></div><div class="modal-footer"><button type="button" class="btn btn-ghost" data-close>关闭</button><button class="btn btn-primary" id="import-submit" type="submit">保存并开始处理</button></div></form>`);
 const input=document.querySelector('#file-input');input.onchange=e=>{addImportFiles(e.target.files);input.value=''};
 document.querySelector('#dropzone').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();input.click()}};
 if(files.length)addImportFiles(files);if(pasted)dirty=true;drawImportQueue();
 document.querySelector('#import-form').onsubmit=async e=>{
 e.preventDefault();if(importBusy)return;
 const value=id=>document.querySelector('#'+id).value;
 const text=value('transcript-input').trim();if(!text&&!importQueue.some(x=>x.status!=='done'))return toast('请添加录音、文字文件，或粘贴文字稿');
 const options={category:value('category-input'),date:value('date-input'),time:value('time-input'),duration:Number(value('duration-input'))||0,autoAnalyze:document.querySelector('#auto-analyze').checked};
 const title=value('title-input').trim(),paired=hasPairedImportAudio();let saved=0,pastedSaved=false,lastId=null;
 importBusy=true;drawImportQueue();
 try{
 for(const item of importQueue){if(item.status==='done')continue;
 if(!audioFile(item.file)&&!textFile(item.file)||!item.file.size||item.file.size>(audioFile(item.file)?100:5)*1024*1024)continue;
 item.status='running';item.error='';drawImportQueue();
 try{let result;if(audioFile(item.file)){result=await api('import-audio',{method:'POST',body:{...options,duration:item.duration||options.duration,audio:{name:item.file.name,data:await fileBase64(item.file)},text:paired?text:'',title:importQueue.length===1?title:''}})}else{result=await importRecord({...options,text:await item.file.text(),filename:item.file.name,title:importQueue.length===1?title:''})}
 item.status='done';item.id=result.record.id;lastId=item.id;saved++;if(paired&&text)pastedSaved=true;
 }catch(error){item.status='failed';item.error=error.message}drawImportQueue();}
 if(text&&!paired){try{const result=await importRecord({...options,text,title});pastedSaved=true;saved++;lastId=result.record.id}catch(error){toast('粘贴文字未保存：'+error.message)}}
 if(pastedSaved)document.querySelector('#transcript-input').value='';
 await syncData();refresh();
 }catch(error){toast(error.message)}finally{importBusy=false;dirty=importPending();drawImportQueue()}
 if(saved)toast(`已保存 ${saved} 段记录；语音转写与 AI 整理会继续在后台进行`);
 if(!importQueue.length&&pastedSaved&&lastId){dirty=false;openDetail(lastId)}
 };
 return true;
}

function openCategories(){captureDetailDraft();const draft=structuredClone(categories),revision=appState.categoryRevision;showModal(`<div class="modal-head"><div><h2>管理分类</h2><p>新增、改名和调整颜色，让记录按你的方式归档。</p></div>${closeButton}</div><form id="category-form"><div class="modal-body"><div id="category-rows"></div><button type="button" class="btn btn-secondary" id="add-category">${icon('plus')}添加分类</button><p class="form-note">最多 60 类，名称不能重复。删除分类后，其中记录会移回「待确认」。</p><p id="category-error" role="alert"></p></div><div class="modal-footer"><button type="button" class="btn btn-ghost" data-close>取消</button><button class="btn btn-primary" type="submit">保存分类</button></div></form>`);
 const draw=()=>{document.querySelector('#category-rows').innerHTML=draft.map((c,i)=>`<div class="category-edit-row"><input type="color" data-cat-color="${i}" value="${esc(c.color)}" aria-label="${esc(c.name)} 颜色"><input data-cat-name="${i}" value="${esc(c.name)}" required maxlength="24" aria-label="分类名称"><select data-cat-icon="${i}" aria-label="分类图标">${[['work','工作'],['learn','学习'],['life','生活'],['idea','灵感'],['folder','文件夹'],['book','书籍'],['mic','录音'],['clock','时间'],['star','收藏'],['heart','情感'],['coffee','休闲'],['users','人际'],['target','目标'],['message','对话'],['pen','写作'],['music','音乐'],['calendar','日程'],['bookmark','书签'],['plane','旅行']].map(([id,name])=>`<option value="${id}" ${c.icon===id?'selected':''}>${name}</option>`).join('')}</select><button type="button" class="icon-btn danger" data-cat-delete="${i}" aria-label="删除 ${esc(c.name)}" ${c.id==='inbox'?'disabled':''}>${icon('trash')}</button></div>`).join('');for(const [key,field] of [['name','name'],['color','color'],['icon','icon']])document.querySelectorAll(`[data-cat-${key}]`).forEach(el=>el.oninput=()=>{draft[Number(el.dataset['cat'+key[0].toUpperCase()+key.slice(1)])][field]=el.value;dirty=true});document.querySelectorAll('[data-cat-delete]').forEach(el=>el.onclick=()=>{const i=Number(el.dataset.catDelete);if(confirm(`删除「${draft[i].name}」？保存分类后，该分类的记录会移回「待确认」。`)){draft.splice(i,1);dirty=true;draw()}})};
 draw();document.querySelector('#add-category').onclick=()=>{if(draft.length>=60)return toast('最多可添加 60 个分类');draft.push({id:'custom-'+crypto.randomUUID(),name:'',color:'#607646',icon:'folder'});dirty=true;draw();document.querySelector('#category-rows').lastElementChild.querySelector('[data-cat-name]').focus()};
 document.querySelector('#category-form').onsubmit=async e=>{e.preventDefault();const list=draft.map(c=>({...c,name:c.name.trim()}));if(list.some(c=>!c.name))return toast('请填写每个分类名称');if(new Set(list.map(c=>c.name.toLocaleLowerCase())).size!==list.length)return toast('分类名称不能重复');e.submitter.disabled=true;try{await api('categories',{method:'PUT',body:{categories:list,revision}});await syncData();if(!getState().categories.some(c=>c.id===page)&&!names[page])page='all';filter='all';dirty=false;modal.close();refresh();toast('分类已更新')}catch(error){document.querySelector('#category-error').textContent=error.message;e.submitter.disabled=false}};
}

function openDetail(id){
 if(savingDetailForm){toast('正在保存整理，请稍候');return false}
 if(importBusy){toast('正在保存导入队列，请稍候');return false}
 if(!records.some(r=>r.id===id))return false;
 captureDetailDraft();
 tabDraft=null;currentId=id;detailTab='notes';renderDetail();
 restoreDetailDraft(id);
 return true;
}
function renderDetailKeepingDraft(){
 const form=modal.querySelector('#detail-form');
 if(!form||!dirty)return renderDetail();
 const fields=[...form.querySelectorAll('input,textarea,select')].map(el=>({id:el.id,value:el.value,checked:el.checked}));
 const active=document.activeElement,focus=active&&form.contains(active)?{id:active.id,start:active.selectionStart,end:active.selectionEnd}:null;
 const scroll=modal.scrollTop,bodyScroll=form.querySelector('.modal-body')?.scrollTop||0;
 renderDetail();
 for(const field of fields){const el=document.getElementById(field.id);if(el){el.value=field.value;if(el.type==='checkbox')el.checked=field.checked}}
 dirty=true;
 const focused=focus&&document.getElementById(focus.id);if(focused){focused.focus({preventScroll:true});if(focus.start!==null&&typeof focused.setSelectionRange==='function')focused.setSelectionRange(focus.start,focus.end)}
 modal.scrollTop=scroll;const body=modal.querySelector('#detail-form .modal-body');if(body)body.scrollTop=bodyScroll;
}
async function updateDetailMetadata(r,patch,message){
 const form=modal.querySelector('#detail-form');if(!form||savingDetailForm||form.dataset.metadataPending)return;
 form.dataset.metadataPending='true';const buttons=[...form.querySelectorAll('[data-set-value],[data-gem-tag],[type="submit"]')];buttons.forEach(b=>b.disabled=true);
 try{await api('records',{method:'PUT',body:{...r,...patch}});await syncData();refresh();if(modal.open&&currentId===r.id&&form.isConnected)renderDetailKeepingDraft();toast(message)}
 catch(e){
  if(e.status!==409)return toast(e.message);
  /* 版本被后台任务推进时同样 rebase 重试一次 */
  try{await syncData();const fresh=getRecords().find(x=>x.id===r.id);if(!fresh)return toast('此记录已被删除');
   await api('records',{method:'PUT',body:{...fresh,...patch,revision:fresh.revision}});
   await syncData();refresh();if(modal.open&&currentId===r.id&&form.isConnected)renderDetailKeepingDraft();toast(message)}
  catch(e2){toast(e2.message)}
 }
 finally{if(form.isConnected){delete form.dataset.metadataPending;buttons.forEach(b=>b.disabled=false)}}
}
async function saveDetailDraft(form,r){
 if(savingDetailForm||form.dataset.metadataPending)return;
 const v=k=>form.querySelector('#edit-'+k).value.trim();if(!v('title'))return toast('标题不能为空');
 const payload={...r,title:v('title'),category:v('category'),date:v('date'),time:v('time'),summary:v('summary'),highlights:v('highlights').split('\n').filter(Boolean),learnings:v('learnings').split('\n').filter(Boolean),actions:v('actions').split('\n').filter(Boolean),reviewed:form.querySelector('#edit-reviewed').checked};
 const controls=[...modal.querySelectorAll('input,textarea,select,button')].map(el=>({el,disabled:el.disabled}));
 const submit=form.querySelector('[type="submit"]'),submitLabel=submit.innerHTML;
 savingDetailForm=form;controls.forEach(({el})=>el.disabled=true);submit.textContent='正在保存…';
 try{await saveRecord(payload);detailDrafts.delete(r.id);persistDrafts();if(modal.open&&form.isConnected&&currentId===r.id){dirty=false;tabDraft=null;modal.close()}refresh();toast('整理已保存，成长又留下了一点痕迹')}
 catch(e){
  if(e.status!==409)return toast(e.message);
  /* 后台转写/AI 完成推进了版本号：取服务端最新记录做基底，仅保留表单可编辑字段，rebase 后重试一次 */
  try{
   await syncData();const fresh=getRecords().find(x=>x.id===r.id);
   if(!fresh)return toast('此记录已被删除，无法保存');
   const editable={title:payload.title,category:payload.category,date:payload.date,time:payload.time,summary:payload.summary,highlights:payload.highlights,learnings:payload.learnings,actions:payload.actions,reviewed:payload.reviewed};
   await saveRecord({...fresh,revision:fresh.revision,...editable});
   if(modal.open&&form.isConnected&&currentId===r.id){dirty=false;modal.close()}refresh();toast('已合并后台的新转写内容，你的整理保存成功')
  }catch(e2){toast(e2.message)}
 }
 finally{savingDetailForm=null;if(form.isConnected){controls.forEach(({el,disabled})=>el.disabled=disabled);submit.innerHTML=submitLabel}}
}
function renderDetail(){const r=records.find(x=>x.id===currentId);if(!r)return;
 /* 播放状态无需再捕获：宿主 audio 常驻，切标签、轮询刷新、标记干货时控制件重连即可，播放本身不中断 */
 const base=listRecords(),ordered=base.some(x=>x.id===currentId)?base:[...records].sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time));const pos=ordered.findIndex(x=>x.id===currentId),prevId=pos>0?ordered[pos-1].id:null,nextId=pos>-1&&pos<ordered.length-1?ordered[pos+1].id:null;const navBtn=(id,label,flip)=>`<button class="icon-btn" ${id?`data-nav-record="${esc(id)}"`:'disabled aria-disabled="true"'} aria-label="${label}"${flip?' style="transform:rotate(180deg)"':''}>${icon('chevron')}</button>`;showModal(`<div class="modal-head"><div><div class="detail-meta">${categoryTag(r.category)} ${esc(r.date)} · ${esc(r.time)} ${r.demo?'· 演示记录':''}</div><h2>${esc(r.title)}</h2></div><div class="detail-nav">${navBtn(prevId,'上一条记录',true)}${navBtn(nextId,'下一条记录')}</div>${closeButton}</div>${audioPanel(r)}<div class="detail-tabs"><button class="chip ${detailTab==='notes'?'active':''}" data-tab="notes">摘要与整理稿</button><button class="chip ${detailTab==='raw'?'active':''}" data-tab="raw">转写原文</button></div>${detailTab==='raw'?`<div class="modal-body"><p class="form-note">导入的文字原文，仅在本机保存。${r.source?.name?` 来源：${esc(r.source.name)}`:''}</p><pre class="transcript">${esc(r.transcript||'音频还没有文字稿。可等待转写完成，或使用上方入口补贴文字稿。')}</pre></div><div class="modal-footer"><button class="btn btn-secondary" id="export-record">${icon('download')}导出记录</button></div>`:`<form id="detail-form"><div class="modal-body">${aiDetail(r)}<section class="cleaned-block"><h3>去口水词整理稿</h3><p class="form-note">轻度清理语气填充词，保留事实、顺序与原意；可切换原文核对。</p><pre>${esc(r.cleanedTranscript||(['queued','running'].includes(r.ai?.status)?'千问正在处理，整理稿完成后会显示在这里。':'尚未生成，点击上方「开始整理」。'))}</pre></section><div class="form-grid"><div class="field"><label for="edit-title">记录标题</label><input id="edit-title" value="${esc(r.title)}" required maxlength="120"></div><div class="field"><label for="edit-category">场景分类</label><select id="edit-category">${categories.map(c=>`<option value="${c.id}" ${c.id===r.category?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div></div><div class="form-grid"><div class="field"><label>录音价值</label><div class="value-chip-row"><button type="button" class="value-chip ${r.value==='daily'?'active':''}" data-set-value="daily">日常琐碎 · 提炼即可</button><button type="button" class="value-chip ${r.value==='gem'?'active':''}" data-set-value="gem">干货 · 值得复看</button></div></div></div>${r.value==='gem'?`<div class="gem-tag-row"><span class="gem-tag-label">干货标签</span>${['方法论','人脉','决策','知识点','金句'].map(t=>`<button type="button" class="gem-tag-chip ${(r.gemTags||[]).includes(t)?'active':''}" data-gem-tag="${t}">${t}</button>`).join('')}</div>`:''}<div class="form-grid"><div class="field"><label for="edit-date">录音日期</label><input id="edit-date" type="date" required value="${esc(r.date)}"></div><div class="field"><label for="edit-time">录音时间</label><input id="edit-time" type="time" required value="${esc(r.time)}"></div></div>${[['summary','内容摘要','用自己的话，留下这段对话的主线。',r.summary],['highlights','关键片段','每行一个片段，可以附上原文时间戳。',r.highlights.join('\n')],['learnings','学到什么','每行一个学习点，积累可以再次用到的经验。',r.learnings.join('\n')],['actions','下一步行动','每行一个行动，让想法有一个落点。',r.actions.join('\n')]].map(([key,label,placeholder,value])=>`<div class="field detail-section"><label for="edit-${key}">${label}</label><textarea id="edit-${key}" rows="3" placeholder="${placeholder}">${esc(value)}</textarea></div>`).join('')}<label class="check-label"><input type="checkbox" id="edit-reviewed" ${r.reviewed?'checked':''}> 我已经回看并复盘了这段记录</label></div><div class="modal-footer"><button type="button" class="icon-btn danger" id="delete-record" aria-label="删除记录">${icon('trash')}</button><button type="button" class="btn btn-secondary" id="export-record">${icon('download')}导出</button><button class="btn btn-primary" type="submit">${icon('check')}保存整理</button></div></form>`}`);modal.querySelectorAll('[data-nav-record]').forEach(b=>b.onclick=()=>{openDetail(b.dataset.navRecord);modal.focus({preventScroll:true})});modal.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{
 /* 切标签不再丢弃草稿：离开「摘要与整理稿」时暂存未保存内容，切回时原样恢复 */
 if(b.dataset.tab===detailTab)return;
 if(b.dataset.tab==='notes'&&tabDraft){
  detailTab='notes';renderDetail();
  for(const f of tabDraft){const el=document.getElementById(f.id);if(el){el.value=f.value;if(el.type==='checkbox')el.checked=f.checked}}
  dirty=true;tabDraft=null;return;
 }
 if(dirty&&detailTab==='notes'&&modal.querySelector('#detail-form'))tabDraft=[...modal.querySelectorAll('#detail-form input,#detail-form textarea,#detail-form select')].map(el=>({id:el.id,value:el.value,checked:el.checked}));
 detailTab=b.dataset.tab;renderDetail();
});bindAudio(r);const share=document.createElement('div');share.className='record-share-actions';share.innerHTML=`<button type="button" class="btn btn-secondary" id="copy-record-link">复制录音链接</button>${window.__SHENGJI_NATIVE?'<button type="button" class="btn btn-secondary" id="share-record">分享到其他 App</button>':''}`;modal.append(share);document.querySelector('#copy-record-link').onclick=async()=>{const text='shengji://record/'+encodeURIComponent(r.id);try{if(window.webkit?.messageHandlers?.shengji)window.webkit.messageHandlers.shengji.postMessage({action:'copyText',text});else await navigator.clipboard.writeText(text);toast('已复制录音链接')}catch{toast('链接：'+text)}};const shareButton=document.querySelector('#share-record');if(shareButton)shareButton.onclick=()=>window.webkit.messageHandlers.shengji.postMessage({action:'share',content:recordMarkdown(r,cat(r.category).name)});document.querySelector('#export-record').onclick=()=>download(`${r.title}.md`,recordMarkdown(r,cat(r.category).name),'text/markdown');modal.querySelectorAll('[data-analyze]').forEach(b=>b.onclick=()=>requestAnalysis(b.dataset.analyze));modal.querySelectorAll('[data-set-value]').forEach(b=>b.onclick=()=>{const v=b.dataset.setValue;if(r.value!==v)updateDetailMetadata(r,{value:v,valueSource:'user'},v==='gem'?'已标记为干货，进入复看清单':'已归为日常琐碎')});modal.querySelectorAll('[data-gem-tag]').forEach(b=>b.onclick=()=>{const t=b.dataset.gemTag,cur=r.gemTags||[],tags=cur.includes(t)?cur.filter(x=>x!==t):[...cur,t];updateDetailMetadata(r,{gemTags:tags},tags.includes(t)?`已加上「${t}」标签`:`已移除「${t}」标签`)});const form=document.querySelector('#detail-form');if(form){form.onsubmit=e=>{e.preventDefault();saveDetailDraft(form,r)};document.querySelector('#delete-record').onclick=async()=>{if(confirm('确定删除这段记录及其整理内容？删除后 6 秒内可撤销。')){deleting.add(r.id);dirty=false;detailDrafts.delete(r.id);persistDrafts();modal.close();deleteTimers.set(r.id,setTimeout(async()=>{deleteTimers.delete(r.id);try{await deleteRecord(r.id)}catch(e){toast(e.message);deleting.delete(r.id)}refresh()},DELETE_DELAY));refresh();toast(`已删除「${r.title}」`,{label:'撤销',run:()=>cancelDelete(r.id)},6000)}}}}
function download(name,data,type='application/json'){let text=typeof data==='string'?data:JSON.stringify(data,null,2);if(window.webkit?.messageHandlers?.shengji){window.webkit.messageHandlers.shengji.postMessage({action:'export',filename:name,content:text});return;}const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name.replace(/[\\/:*?"<>|]/g,'_');a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function openBackup(){showModal(`<div class="modal-head"><div><h2>数据备份与恢复</h2><p>把属于自己的记忆，好好留存。</p></div>${closeButton}</div><div class="modal-body"><div class="detail-section"><h3>导出完整备份</h3><p>包含音频、原文、分类、复盘和收藏。建议定期保存到自己的文件夹。</p><button class="btn btn-primary" id="backup-export">${icon('download')}导出 JSON 备份</button></div><div class="detail-section"><h3>从备份恢复</h3><p>恢复会替换当前全部记录。请先导出当前数据。</p><label class="btn btn-secondary" tabindex="0" role="button" id="backup-label">${icon('upload')}选择备份文件<input type="file" id="backup-import" accept=".json" hidden></label></div><p class="form-note">记录与原文保存在本机应用数据目录；不会随浏览器缓存清理而消失。JSON 备份可随时迁移到另一台电脑。</p></div>`);document.querySelector('#backup-label').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();document.querySelector('#backup-import').click()}};document.querySelector('#backup-export').onclick=async()=>{try{download(`声迹备份-${today}.json`,await exportData())}catch(e){toast(e.message)}};document.querySelector('#backup-import').onchange=async e=>{let f=e.target.files[0];if(!f)return;if(f.size>500*1024*1024)return toast('备份过大，最大支持 500 MB');if(!confirm('确定用此备份替换当前所有记录吗？'))return;try{await importBackup(await f.text());detailDrafts.clear();persistDrafts();dirty=false;modal.close();refresh();toast('备份已恢复')}catch(err){toast('恢复失败：'+err.message)}}}
boot();

/* 草稿已实时持久化到 localStorage，刷新或关闭后回到对应记录即可恢复，无需 beforeunload 拦截 */
function aiBadge(r){const status=r.ai?.status;return status&&status!=='none'?`<span class="ai-badge ${status}">${icon('spark')}${({queued:'AI 等待整理',running:'AI 正在整理',done:'AI 已整理',failed:'AI 整理失败'})[status]||''}</span>`:''}
function aiDetail(r){const progress=r.ai?.cleanupProgress,showProgress=r.ai?.status==='running'&&r.ai?.phase==='cleanup'&&Number.isInteger(progress?.done)&&Number.isInteger(progress?.total);return `<section class="ai-result ${r.ai?.status||'none'}"><div class="ai-result-heading"><strong>${icon('spark')} ${r.ai?.status==='done'?'本地 AI 整理完成':r.ai?.status==='running'?(r.ai.phase==='cleanup'?(showProgress?`正在去除口水词（${progress.done}/${progress.total}）`:'正在去除口水词'):'正在生成录音摘要'):r.ai?.status==='queued'?'已经加入整理队列':r.ai?.status==='failed'?'整理暂未完成':'让 AI 帮你整理'}</strong><button type="button" class="btn btn-secondary" data-analyze="${esc(r.id)}" ${!r.transcript||['running','queued'].includes(r.ai?.status)?'disabled':''}>${r.ai?.status==='done'?'重新整理':'开始整理'}</button></div><p>${esc(r.ai?.error||r.ai?.reason||(['queued','running'].includes(r.ai?.status)?'原文已安全保存。你可以关闭这个窗口，声迹会继续处理。':(r.transcript?'自动去除口水词，生成整理稿、摘要、标题与分类。':'有了文字稿后，才能继续 AI 分类整理。')))}</p>${r.ai?.status==='done'&&r.cleanup?.chunksFailed>0?`<p>有 ${r.cleanup.chunksFailed} 块未能清理，已保留原文。</p>`:''}${r.ai?.status==='done'?`<small>${esc(r.ai.model)} · 本机处理 · ${r.ai.coverage?.chunks||1} 个文本段 · AI 内容可修改，关键片段已与原文逐字比对。</small>`:''}${r.source?.dateBasis?`<small>日期依据：${esc(r.source.dateBasis)}。${['watch','connector'].includes(r.source.kind)?'如与录音时间不同，可在下方更正。':''}</small>`:''}</section>`}
function automationStrip(){const s=appState.settings;const jobs=records.filter(r=>['queued','running'].includes(r.ai?.status));const failed=records.filter(r=>r.ai?.status==='failed'||r.transcription?.status==='failed');const voices=records.filter(r=>['queued','running'].includes(r.transcription?.status));return `<section class="automation-strip${jobs.length||voices.length?' processing':''}"><div class="automation-orb">${icon('spark')}</div><div class="automation-copy"><strong>${voices.length?`${voices.length} 段语音正在转写${jobs.length?` · ${jobs.length} 段文字待整理`:''}`:jobs.length?`正在替你整理 ${jobs.length} 段声音`:s.watchEnabled?'自动收集已开启':'自动收集已暂停'}</strong><p>${appState.watch.error?esc(appState.watch.error):s.watchEnabled?`监测「${esc((s.watchFolder||'').split('/').pop())}」 · ${s.autoAnalyze?'自动分类、命名与整理':'仅导入原文'}${failed.length?` · ${failed.length} 段需重试`:''}`:'开启后，录音或文字文件放进指定文件夹即可。'}</p></div><button class="btn btn-secondary" data-action="automation">管理 ${icon('chevron')}</button></section>`}
async function requestAnalysis(id){captureDetailDraft();const r=records.find(r=>r.id===id);if(r?.ai?.status==='done'&&!confirm('重新整理将替换当前标题、分类、摘要与学习点，确定继续吗？'))return;try{await api('analyze',{method:'POST',body:{id}});await syncData();refresh();dirty=false;renderDetail();toast('已加入本地 AI 整理队列')}catch(e){toast(e.message)}}
async function openAutomation(){const s=appState.settings;showModal(`<div class="modal-head"><div><div class="eyebrow">YOUR QUIET ASSISTANT</div><h2>让记录，自己发生</h2><p>录音或文字保存到文件夹后，声迹会接着完成后面的事。</p></div>${closeButton}</div><form id="automation-form"><div class="modal-body"><div class="automation-flow"><span>录音 / 文字</span>${icon('arrow')}<span>本地语音转写</span>${icon('arrow')}<span>千问整理＋摘要</span></div><label class="check-label setting-switch"><input type="checkbox" id="watch-enabled" ${s.watchEnabled?'checked':''}><span><strong>监测文件夹，自动添加新记录</strong><small>应用运行时每 5 秒检查一次，文件写入稳定后导入。</small></span></label><div class="field"><label for="watch-folder">录音与文字收件夹</label><div class="folder-input"><input id="watch-folder" value="${esc(s.watchFolder||'')}" required placeholder="转写文件所在文件夹的完整路径"><button type="button" class="btn btn-secondary" id="choose-folder">${window.__SHENGJI_NATIVE?'选择文件夹':'默认收件箱'}</button></div><small>仅监测此文件夹内的 MP3、M4A、WAV（每个最多 100 MB）及 TXT、MD、SRT、VTT（每个最多 5 MB）。录音先转写，再整理；相同内容不会重复添加。</small></div><div class="settings-inline"><button type="button" class="btn btn-ghost" id="open-inbox">${icon('folder')}打开当前收件箱</button><button type="button" class="btn btn-ghost" id="scan-now">${icon('check')}立即检查</button></div><label class="check-label setting-switch"><input type="checkbox" id="auto-enabled" ${s.autoAnalyze?'checked':''}><span><strong>新记录自动交给 AI 整理</strong><small>先去口水词，再生成摘要、标题、分类、关键原话与行动项。</small></span></label><div class="field"><label for="ai-model">整理与摘要模型（千问）</label><select id="ai-model"><option value="qwen2.5:7b" ${s.model==='qwen2.5:7b'?'selected':''}>Qwen 2.5 · 7B · 更轻快</option><option value="qwen3:14b" ${s.model==='qwen3:14b'?'selected':''}>Qwen 3 · 14B · 更细致</option></select></div><div class="model-status" id="model-status" role="status">正在检查本地模型……</div>${window.__SHENGJI_NATIVE?'<button type="button" class="btn btn-ghost" id="start-ollama">打开本地模型服务</button>':''}<div class="settings-note">${icon('mic')}<p>文字留在本机，由 Ollama 运行模型。分类不确定时进入「待确认」。整理失败会保留原文，并提供重试入口。</p></div><p class="form-note">关闭应用窗口后会继续收集；从菜单退出声迹后暂停。下次打开会接着检查。数据目录：${esc(appState.dataDir||'')}</p></div><div class="modal-footer"><button type="button" class="btn btn-ghost" data-close>取消</button><button class="btn btn-primary" type="submit">${icon('check')}保存设置</button></div></form>`);modal.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal);const startOllama=document.querySelector('#start-ollama');if(startOllama)startOllama.onclick=()=>window.webkit.messageHandlers.shengji.postMessage({action:'startOllama'});document.querySelector('#choose-folder').onclick=()=>{if(window.webkit?.messageHandlers?.shengji)window.webkit.messageHandlers.shengji.postMessage({action:'chooseFolder'});else{document.querySelector('#watch-folder').value=appState.defaultInbox;dirty=true}};document.querySelector('#open-inbox').onclick=()=>{const folder=document.querySelector('#watch-folder').value;if(window.webkit?.messageHandlers?.shengji)window.webkit.messageHandlers.shengji.postMessage({action:'openFolder',path:folder});else toast('文件夹路径：'+folder)};document.querySelector('#scan-now').onclick=async()=>{try{const result=await api('scan',{method:'POST',body:{}});toast(result.error||'已检查已保存的监测目录；新文件稳定后会在下一次检查导入')}catch(e){toast(e.message)}};document.querySelector('#automation-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{await api('settings',{method:'PUT',body:{watchFolder:document.querySelector('#watch-folder').value.trim(),watchEnabled:document.querySelector('#watch-enabled').checked,autoAnalyze:document.querySelector('#auto-enabled').checked,model:document.querySelector('#ai-model').value}});dirty=false;modal.close();await syncData();refresh();toast('自动整理设置已保存')}catch(e){toast(e.message);button.disabled=false}};try{const result=await api('models');const el=document.querySelector('#model-status');if(el){let text=result.available&&result.models.length?`● 本机已就绪：${result.models.map(m=>m.id).join('、')}`:result.error||'本机尚未安装支持的 Qwen 模型，请在 Ollama 中安装后再试';if(result.available&&result.memoryGB&&result.memoryGB<16&&result.models.some(m=>String(m.id).includes('14b')))text+=`。本机内存 ${result.memoryGB}GB，运行 14B 模型可能吃紧，建议优先使用 7B`;el.textContent=text;el.classList.toggle('ready',result.available&&result.models.length>0)}}catch(e){const el=document.querySelector('#model-status');if(el)el.textContent=e.message}}
window.addEventListener('shengji-folder',e=>{const el=document.querySelector('#watch-folder');if(el&&e.detail?.path){el.value=e.detail.path;dirty=true}});
window.addEventListener('shengji-export',e=>{if(e.detail?.error)toast(e.detail.error);else if(e.detail?.path)toast('已导出到 '+e.detail.path)});
async function boot(){bindPalette({dialog:document.querySelector('#palette'),icon,getRecords:()=>records,getCategories:()=>categories,goto:p=>{page=p;filter='all';query='';selectedDate='';refresh()},openRecord:openDetail,toast,actions:[{icon:'upload',label:'导入录音 / 文字',run:()=>openImport()},{icon:'spark',label:'自动整理设置',run:()=>openAutomation()},{icon:'download',label:'数据备份与恢复',run:()=>openBackup()},{icon:'zap',label:'键盘快捷键',run:()=>openShortcuts()}]});document.querySelector('#app').innerHTML='<div class="boot-state"><h1>声迹</h1><p>正在打开你的声音记忆……</p></div>';try{await initData();connectionError='';refresh();startPolling()}catch(e){document.querySelector('#app').innerHTML=`<div class="boot-state"><h1>声迹</h1><p>${esc(e.message)}</p><button class="btn btn-primary" id="retry-boot">重新连接</button><p class="form-note">请打开「声迹.app」，应用会自动启动本地服务。</p></div>`;document.querySelector('#retry-boot').onclick=boot}}
let pollTimer=null,pollBusy=false;
function startPolling(){clearInterval(pollTimer);pollTimer=setInterval(async()=>{if(pollBusy)return;pollBusy=true;try{
 /* 轮询先问一个标量端点：库没变化就不拉全量状态（大库下每 2.5s 5MB 的税归零） */
 const rev=await api('revision');
 const unchanged=rev.revision===appState.revision&&rev.categoryRevision===appState.categoryRevision&&rev.watchError===appState.watch.error;
 if(unchanged){const recovered=Boolean(connectionError);connectionError='';appState.watch.lastScan=rev.lastScan;if(recovered)render();return}
 const oldRecord=records.find(r=>r.id===currentId);await syncData();const next=getState();const changed=next.revision!==appState.revision||next.categoryRevision!==appState.categoryRevision||next.watch.error!==appState.watch.error||connectionError;connectionError='';if(changed){refresh();const updated=records.find(r=>r.id===currentId);if(modal.open&&!dirty&&!savingDetailForm&&(modal.querySelector('#detail-form')||modal.querySelector('.transcript'))&&JSON.stringify(oldRecord)!==JSON.stringify(updated)){if(updated)renderDetail();else{modal.close();toast('此记录已从资料库中移除')}}}}catch(e){if(!connectionError){connectionError=e.message;render()}}finally{pollBusy=false}},2500)}

window.__shengjiHasUnsavedChanges=()=>Boolean(dirty||savingDetailForm)&&modal.open||detailDrafts.size>0;
window.addEventListener('shengji-model',e=>{toast(e.detail?.error||e.detail?.message||'正在打开本地模型服务')});

function transcriptionBadge(r){if(!r.audio)return '';const status=r.transcription?.status|| (r.transcript?'done':'queued');return `<span class="transcription-badge ${status}">${icon('mic')}${({queued:'语音待转写',running:'语音转写中',done:'文字稿已就绪',failed:'语音转写失败'})[status]||'音频已保存'}</span>`}
function audioPanel(r){if(!r.audio)return '';const bars=Array.from({length:26},(_,i)=>10+Math.round(Math.abs(Math.sin(i*1.7+r.audio.name.length))*62));return `<section class="audio-panel"><div class="audio-heading"><strong>${icon('mic')} ${esc(r.audio.name)}</strong>${transcriptionBadge(r)}</div><div class="audio-player" id="audio-player" data-state="paused"><button type="button" class="audio-play" id="audio-play" aria-label="播放 ${esc(r.audio.name)}"><span class="when-paused">${icon('play')}</span><span class="when-playing">${icon('pause')}</span></button><div class="audio-wave" aria-hidden="true">${bars.map((h,i)=>`<i style="height:${h}%;--i:${i}"></i>`).join('')}</div><span class="audio-time" id="audio-current">0:00</span><input type="range" class="audio-seek" id="audio-seek" min="0" max="100" value="0" step="0.1" aria-label="播放进度"><span class="audio-time" id="audio-duration">--:--</span><button type="button" class="audio-speed" id="audio-speed" aria-label="切换播放速度" title="切换播放速度">1×</button></div><p id="audio-load-status" class="form-note">正在加载本机音频…</p>${r.transcription?.error?`<p class="audio-error" role="alert">${esc(r.transcription.error)}</p>`:''}${!r.transcript?`<div class="audio-actions"><button type="button" class="btn btn-secondary" id="retry-transcription" ${['queued','running'].includes(r.transcription?.status)?'disabled':''}>${r.transcription?.status==='failed'?'重试语音转写':'开始语音转写'}</button><button type="button" class="btn btn-ghost" id="supplement-transcript">已有文字稿？补贴原文</button></div>`:''}<p class="form-note">${r.transcription?.engine?`转写引擎：${esc(r.transcription.engine)} · `:''}音频保留在本机，可随时回放。</p></section>`}
function bindAudio(r){if(!r.audio)return;
 /* 弹窗控制件每次随 renderDetail 重建，这里只把它们接到常驻的宿主 audio 上 */
 const wrap=document.querySelector('#audio-player'),playBtn=document.querySelector('#audio-play'),seek=document.querySelector('#audio-seek'),speedBtn=document.querySelector('#audio-speed');
 if(wrap&&playBtn&&seek){
  playBtn.onclick=toggleAudio;
  seek.oninput=()=>{audioScrubEl=seek;if(Number.isFinite(audioEl.duration))audioEl.currentTime=Number(seek.value)};
  seek.onchange=()=>{if(audioScrubEl===seek)audioScrubEl=null};
  if(speedBtn){speedBtn.textContent=(savedPlaybackRate===1?'1':savedPlaybackRate)+'×';speedBtn.onclick=()=>{savedPlaybackRate=SPEED_STEPS[(SPEED_STEPS.indexOf(savedPlaybackRate)+1)%SPEED_STEPS.length];try{localStorage.setItem(RATE_KEY,String(savedPlaybackRate))}catch{}audioEl.playbackRate=savedPlaybackRate;speedBtn.textContent=(savedPlaybackRate===1?'1':savedPlaybackRate)+'×'};audioEl.playbackRate=savedPlaybackRate}
 }
 const statusEl=()=>document.querySelector('#audio-load-status');
 if(audioEl.dataset.recordId===r.id&&audioEl.src&&!audioEl.error){
  /* 同一条记录：控制件直接重连，播放位置与播放态原样保留（宿主即续播状态） */
  if(statusEl())statusEl().textContent='';
  syncAudioState();syncAudioTime();
 }else{
  /* 换了一条记录：旧 objectURL 立即回收，加载新音频并复位播放态 */
  releaseAudio();const generation=audioLoadVersion;
  audioEl.pause();audioEl.removeAttribute('src');audioEl.load();
  audioEl.dataset.recordId=r.id;audioEl.dataset.audioName=r.audio.name;
  audioURL(r.id).then(url=>{if(generation!==audioLoadVersion){URL.revokeObjectURL(url);return}audioObjectURL=url;audioEl.src=url;if(statusEl())statusEl().textContent='';audioEl.onerror=()=>{const el=statusEl();if(el)el.textContent='此音频编码暂时无法回放，原文件仍已保存。'}}).catch(error=>{if(generation===audioLoadVersion){const el=statusEl();if(el)el.textContent=error.message}});
 }
 const retry=document.querySelector('#retry-transcription');if(retry)retry.onclick=async()=>{captureDetailDraft();retry.disabled=true;try{await api('transcribe',{method:'POST',body:{id:r.id}});await syncData();refresh();dirty=false;renderDetail();toast('已加入语音转写队列')}catch(error){toast(error.message);retry.disabled=false}};
 const supplement=document.querySelector('#supplement-transcript');if(supplement)supplement.onclick=()=>openSupplement(r);
}
function openSupplement(r){captureDetailDraft();showModal(`<div class="modal-head"><div><h2>给录音补充文字稿</h2><p>${esc(r.title)}</p></div>${closeButton}</div><form id="supplement-form"><div class="modal-body"><label class="btn btn-secondary">选择 TXT / MD / SRT / VTT<input type="file" id="supplement-file" accept=".txt,.md,.srt,.vtt" hidden></label><div class="field"><label for="supplement-text">转写原文</label><textarea id="supplement-text" rows="10" maxlength="500000" required placeholder="粘贴这段录音对应的文字稿"></textarea></div><label class="check-label"><input type="checkbox" id="supplement-auto" ${appState.settings.autoAnalyze!==false?'checked':''}>保存后自动整理</label><p class="form-note">只补充尚无原文的音频；已有文字不会被覆盖。</p></div><div class="modal-footer"><button type="button" class="btn btn-ghost" data-close>取消</button><button class="btn btn-primary" type="submit">保存文字稿</button></div></form>`);let supplementSource=null;document.querySelector('#supplement-text').addEventListener('input',()=>{supplementSource=null});document.querySelector('#supplement-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(!textFile(f)||f.size>5*1024*1024)return toast('请选择最多 5 MB 的 TXT、MD、SRT 或 VTT');try{const raw=await f.text();document.querySelector('#supplement-text').value=parseTranscript(raw,f.name);supplementSource={text:raw,filename:f.name};dirty=true}catch(error){toast(error.message)}};document.querySelector('#supplement-form').onsubmit=async e=>{e.preventDefault();const text=document.querySelector('#supplement-text').value.trim();if(!text)return toast('请填写文字稿');e.submitter.disabled=true;try{await api('transcript',{method:'POST',body:{id:r.id,revision:r.revision,text:supplementSource?.text??text,filename:supplementSource?.filename??'',autoAnalyze:document.querySelector('#supplement-auto').checked}});await syncData();refresh();dirty=false;openDetail(r.id);toast('文字稿已保存')}catch(error){toast(error.message);e.submitter.disabled=false}}}
let dragDepth=0;
function dropOverlay(show){let el=document.querySelector('#global-drop');if(!el){el=document.createElement('div');el.id='global-drop';el.className='global-drop';el.innerHTML='<div><strong>松手，把这段声音留下来</strong><p>MP3 · M4A · WAV（100 MB）<br>TXT · MD · SRT · VTT（5 MB）</p></div>';document.body.append(el)}el.hidden=!show}
const carriesFiles=e=>Array.from(e.dataTransfer?.types||[]).includes('Files');
async function importDroppedAudio(files){
 importBusy=true;const failed=[];let saved=0;page='queue';render();toast('正在保存录音，随后自动转写…');
 try{for(const file of files){try{if(!file.size||file.size>100*1024*1024)throw new Error('音频须为 1 字节至 100 MB');await api('import-audio',{method:'POST',body:{audio:{name:file.name,data:await fileBase64(file)},autoAnalyze:appState.settings.autoAnalyze!==false}});saved++}catch(e){failed.push({file,error:e.message})}}await syncData();refresh()}
 finally{importBusy=false}if(failed.length&&openImport(failed.map(x=>x.file))){importQueue.forEach((x,i)=>{x.status='failed';x.error=failed[i]?.error||'导入失败'});drawImportQueue()}toast(`已保存 ${saved} 段录音${failed.length?`，${failed.length} 段未成功，可重试`:'，后台会自动转写与整理'}`);
}
document.addEventListener('dragenter',e=>{if(!carriesFiles(e))return;e.preventDefault();dragDepth++;dropOverlay(true)});
document.addEventListener('dragover',e=>{if(!carriesFiles(e))return;e.preventDefault();e.dataTransfer.dropEffect='copy'});
document.addEventListener('dragleave',e=>{if(!carriesFiles(e))return;dragDepth=Math.max(0,dragDepth-1);if(!dragDepth)dropOverlay(false)});
document.addEventListener('drop',e=>{if(!carriesFiles(e))return;e.preventDefault();e.stopPropagation();dragDepth=0;dropOverlay(false);if(importBusy)return toast('正在保存队列，请稍候再添加文件');const files=Array.from(e.dataTransfer.files);if(!files.length)return;if(!modal.open&&files.every(audioFile))importDroppedAudio(files).catch(e=>toast(e.message));else if(modal.open&&document.querySelector('#import-form'))addImportFiles(files);else openImport(files)});
document.addEventListener('paste',e=>{if(e.target.closest?.('input,textarea,[contenteditable="true"]'))return;const files=Array.from(e.clipboardData?.files||[]);if(files.length){e.preventDefault();if(importBusy)return toast('正在保存队列，请稍候');if(modal.open&&document.querySelector('#import-form'))addImportFiles(files);else openImport(files);return}const text=e.clipboardData?.getData('text/plain')?.trim();if(!text)return;e.preventDefault();if(modal.open&&document.querySelector('#import-form')){document.querySelector('#transcript-input').value=text;dirty=true}else openImport([],text)});
modal.addEventListener('close',()=>{tabDraft=null;if(audioActive())showMiniPlayer();else hideMiniPlayer()});

window.addEventListener('shengji-open-record',async e=>{await syncData();refresh();if(records.some(r=>r.id===e.detail?.id))openDetail(e.detail.id);else toast('这条录音不在当前资料库中')});
window.addEventListener('shengji-import-result',async e=>{await syncData();refresh();toast(e.detail?.error||'已导入录音，后台正在处理');if(e.detail?.id)openDetail(e.detail.id)});
let digestBusy=false;
function digestCard(){const d=(appState.digests||{})[today],count=records.filter(r=>r.date===today).length,btn=!d&&!count?'':digestBusy?'<button type="button" class="btn btn-secondary" disabled>提炼中…</button>':d?`<button type="button" class="btn btn-secondary" data-action="digest" data-digest-date="${today}">重新提炼</button>`:`<button type="button" class="btn btn-secondary" data-action="digest" data-digest-date="${today}">提炼今天</button>`;return `<section class="digest-card"><div class="section-head"><h2>今日提炼 <span>${Number(today.slice(5,7))}月${Number(today.slice(8))}日</span></h2>${btn}${d?`<button type="button" class="text-btn export-btn" data-export="digest">导出</button>`:''}</div>${d?`<div class="digest-text">${esc(d.text)}</div>`:`<p class="digest-hint">${count?`今天已有 ${count} 段记录，提炼一下这一天都做了什么。`:'今天还没有记录，导入或说一段给未来的自己。'}</p>`}</section>`}
async function runDigest(date){if(digestBusy)return;digestBusy=true;refresh();try{await api('digest',{method:'POST',body:{date}});await syncData();digestBusy=false;refresh();toast(date===today?'今日提炼已生成':'这一天已提炼完成')}catch(e){digestBusy=false;refresh();toast(e.message)}}
let gemTagFilter='';
function compoundSection(list){const gems=list.filter(r=>r.value==='gem').sort((a,b)=>String(a.lastReviewedAt||'').localeCompare(String(b.lastReviewedAt||''))||String(b.date).localeCompare(String(a.date)));const shown=gemTagFilter?gems.filter(g=>(g.gemTags||[]).includes(gemTagFilter)):gems;return `<div class="section-head"><h2>复利 · 值得复看</h2><span>${shown.length} 条干货</span>${shown.length?`<button type="button" class="text-btn export-btn" data-export-gems>${icon('download')}导出全部</button>`:''}</div>${gems.length?`<div class="tag-filter-row">${['','方法论','人脉','决策','知识点','金句'].filter(t=>!t||gems.some(g=>(g.gemTags||[]).includes(t))).map(t=>`<button type="button" class="chip ${gemTagFilter===t?'active':''}" data-gem-filter="${t}">${t||'全部'}</button>`).join('')}</div><div class="record-list">${shown.map(gemCard).join('')}</div>`:`<div class="empty-state">${icon('star')}<h3>还没有标记出干货</h3><p>把贵人指点、方法干货标记出来，它们值得反复看。</p></div>`}`}
const gemCard=r=>recordCard(r).replace('</article>',`<button type="button" class="btn btn-secondary review-gem-btn" data-review-gem="${esc(r.id)}">复看</button></article>`);
const GEM_REVIEW_DAYS=7;
const weekStart=t=>{const d=new Date(t+'T00:00:00');d.setDate(d.getDate()-(d.getDay()+6)%7);return localDate(d)};
const weekEnd=t=>{const d=new Date(weekStart(t)+'T00:00:00');d.setDate(d.getDate()+6);return localDate(d)};
const monthISO=(d=today)=>d.slice(0,7);
const iso2cn=s=>s.length===7?`${Number(s.slice(5,7))}月`:`${Number(s.slice(5,7))}月${Number(s.slice(8))}日`;
let weeklyBusy=false;
function reviewReminder(){const cands=records.filter(r=>r.value==='gem').map(r=>({r,overdue:Math.floor((new Date(today)-new Date(r.lastReviewedAt||r.date))/864e5)})).filter(x=>x.overdue>=GEM_REVIEW_DAYS).sort((a,b)=>b.overdue-a.overdue).slice(0,3);if(!cands.length)return '';return `<section class="review-reminder"><div class="section-head"><h2>复看提醒</h2></div>${cands.map(({r,overdue})=>`<div class="review-reminder-row"><span class="review-reminder-text">「${esc(r.title)}」 ${overdue} 天没复看了</span><button type="button" class="btn btn-secondary review-gem-btn" data-review-gem="${esc(r.id)}">复看</button></div>`).join('')}</section>`}
function weeklyCard(){const ws=weekStart(today),we=weekEnd(today),w=(appState.weeklies||{})[ws],n=records.filter(r=>r.date>=ws&&r.date<=we).length;if(!w&&!n)return '';const btn=weeklyBusy?'<button type="button" class="btn btn-secondary" disabled>提炼中…</button>':`<button type="button" class="btn btn-secondary" data-action="weekly">${w?'重新提炼本周':'提炼本周'}</button>`;return `<section class="digest-card weekly-card"><div class="section-head"><h2>本周提炼 <span>${Number(ws.slice(5,7))}月${Number(ws.slice(8))}日至${Number(we.slice(5,7))}月${Number(we.slice(8))}日</span></h2>${btn}${w?`<button type="button" class="text-btn export-btn" data-export="weekly">导出</button>`:''}</div>${w?`<div class="digest-text">${esc(w.text)}</div>`:`<p class="digest-hint">本周已有 ${n} 段记录，汇总一下这一周。</p>`}</section>`}
async function runWeekly(){if(weeklyBusy)return;weeklyBusy=true;refresh();try{await api('weekly',{method:'POST',body:{date:today}});await syncData();weeklyBusy=false;refresh();toast('本周提炼已生成')}catch(e){weeklyBusy=false;refresh();toast(e.message)}}
let monthlyBusy=false;
function monthlyCard(){const m=monthISO(),mo=(appState.monthlies||{})[m],n=records.filter(r=>r.date.slice(0,7)===m).length;if(!mo&&!n)return '';const btn=monthlyBusy?'<button type="button" class="btn btn-secondary" disabled>提炼中…</button>':`<button type="button" class="btn btn-secondary" data-action="monthly">${mo?'重新提炼本月':'提炼本月'}</button>`;return `<section class="digest-card monthly-card"><div class="section-head"><h2>本月提炼 <span>${Number(m.slice(5,7))}月</span></h2>${btn}${mo?`<button type="button" class="text-btn export-btn" data-export="monthly">导出</button>`:''}</div>${mo?`<div class="digest-text">${esc(mo.text)}</div>`:`<p class="digest-hint">本月已有 ${n} 段记录，回顾一下这个月。</p>`}</section>`}
async function runMonthly(){if(monthlyBusy)return;monthlyBusy=true;refresh();try{await api('monthly',{method:'POST',body:{month:monthISO()}});await syncData();monthlyBusy=false;refresh();toast('本月提炼已生成')}catch(e){monthlyBusy=false;refresh();toast(e.message)}}
let yearlyBusy=false;
function yearlyCard(){const y=today.slice(0,4),yr=(appState.yearlies||{})[y],n=records.filter(r=>r.date.slice(0,4)===y).length;if(!yr&&!n)return '';const btn=yearlyBusy?'<button type="button" class="btn btn-secondary" disabled>提炼中…</button>':`<button type="button" class="btn btn-secondary" data-action="yearly">${yr?'重新提炼今年':'提炼今年'}</button>`;return `<section class="digest-card yearly-card"><div class="section-head"><h2>年度回顾 <span>${y}年</span></h2>${btn}${yr?`<button type="button" class="text-btn export-btn" data-export="yearly">导出</button>`:''}</div>${yr?`<div class="digest-text">${esc(yr.text)}</div>`:`<p class="digest-hint">今年已有 ${n} 段记录，回顾这一年。</p>`}</section>`}
async function runYearly(){if(yearlyBusy)return;yearlyBusy=true;refresh();try{await api('yearly',{method:'POST',body:{year:today.slice(0,4)}});await syncData();yearlyBusy=false;refresh();toast('年度回顾已生成')}catch(e){yearlyBusy=false;refresh();toast(e.message)}}
function heatmap(){const y=Number(today.slice(0,4)),m=Number(today.slice(5,7)),first=(new Date(y,m-1,1).getDay()+6)%7,days=new Date(y,m,0).getDate(),byDate={};records.filter(r=>r.date.slice(0,7)===today.slice(0,7)).forEach(r=>{byDate[r.date]=(byDate[r.date]||0)+1});const total=Object.values(byDate).reduce((a,b)=>a+b,0),voiced=Object.keys(byDate).length,cells=Array.from({length:first},()=>'<span></span>');for(let d=1;d<=days;d++){const date=`${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`,n=byDate[date]||0,future=date>today;cells.push(`<button type="button" class="heat-cell ${n>=4?'h3':n>=2?'h2':n?'h1':'h0'}${future?' future':''}" data-date="${date}" title="${m}月${d}日 · ${n} 段记录"${future?' disabled':''}>${d}</button>`)}return `<section class="heatmap-card"><div class="heat-head"><h2>本月足迹</h2><span>本月 ${total} 段 · ${voiced} 天有声</span></div><div class="heat-grid">${'一二三四五六日'.split('').map(d=>`<span class="heat-weekday">${d}</span>`).join('')}</div><div class="heat-grid">${cells.join('')}</div></section>`}
let flashGemId='',flashAt=0;
function gemFlash(){const gems=records.filter(r=>r.value==='gem');if(!gems.length)return '';if(!flashGemId||!gems.some(g=>g.id===flashGemId)||Date.now()-flashAt>600000){const pick=gems[Math.floor(Math.random()*gems.length)];flashGemId=pick.id;flashAt=Date.now()}const g=gems.find(x=>x.id===flashGemId),raw=g.summary||g.highlights[0]||'',brief=raw.length>80?raw.slice(0,80)+'…':raw;return `<section class="gem-flash"><div class="section-head"><h2>随机回顾</h2></div><h3 class="gem-flash-title">${esc(g.title)}</h3>${brief?`<p class="digest-text">${esc(brief)}</p>`:''}<small>${(g.gemTags||[]).map(t=>`<span class="gem-mini-tag">${esc(t)}</span>`).join('')}<span>${dateLabel(g.date)}</span></small><div class="gem-flash-actions"><button type="button" class="btn btn-secondary" data-flash-another>换一条</button><button type="button" class="btn btn-secondary review-gem-btn" data-review-gem="${esc(g.id)}">复看</button></div></section>`}
/* 回顾档案：汇集全部日/周/月/年提炼，随时回看与导出 */
function recapEntries(){
 const out=[],digests=appState.digests||{},weeklies=appState.weeklies||{},monthlies=appState.monthlies||{},yearlies=appState.yearlies||{};
 for(const [key,item] of Object.entries(digests))out.push({type:'digest',key,item,title:`日提炼 · ${iso2cn(key)}`,when:key});
 for(const [key,item] of Object.entries(weeklies))out.push({type:'weekly',key,item,title:`周提炼 · ${iso2cn(item.start||key)}至${iso2cn(item.end||key)}`,when:item.start||key});
 for(const [key,item] of Object.entries(monthlies))out.push({type:'monthly',key,item,title:`月度回顾 · ${Number(key.slice(5,7))}月`,when:key});
 for(const [key,item] of Object.entries(yearlies))out.push({type:'yearly',key,item,title:`年度回顾 · ${key}年`,when:key});
 return out.sort((a,b)=>String(b.when).localeCompare(String(a.when)));
}
function recapFilename(e){return e.type==='digest'?`声迹今日提炼-${iso2cn(e.key)}.md`:e.type==='weekly'?`声迹周报-${iso2cn(e.item.start||e.key)}至${iso2cn(e.item.end||e.key)}.md`:e.type==='monthly'?`声迹月报-${Number(e.key.slice(5,7))}月.md`:`声迹年报-${e.key}年.md`}
function recapMarkdown(e){const h=e.type==='digest'?`# 今日提炼 ${iso2cn(e.key)}`:e.type==='weekly'?`# 本周提炼 ${iso2cn(e.item.start||e.key)}至${iso2cn(e.item.end||e.key)}`:e.type==='monthly'?`# 本月提炼 ${Number(e.key.slice(5,7))}月`:`# 年度回顾 ${e.key}年`;return `${h}\n\n${e.item.text}\n`}
function recapsPage(){
 const entries=recapEntries();
 if(!entries.length)return `<section class="panel"><h2>回顾档案</h2><p>这里会汇集每一份日提炼、周报、月度回顾与年度回顾，按时间倒序供你随时回看。</p><p class="form-note">在首页「提炼今天 / 提炼本周」或每日足迹的「提炼这一天」生成后，就会出现在这里。</p><button class="btn btn-secondary" data-page="home">去首页提炼 ${icon('arrow')}</button></section>`;
 const groups=[['digest','每日'],['weekly','每周'],['monthly','每月'],['yearly','每年']];
 return `<section class="panel recap-head"><div class="section-head"><h2>回顾档案 <span>${entries.length} 份</span></h2><button type="button" class="text-btn export-btn" data-recap-export-all>${icon('download')}导出全部</button></div><p class="form-note">全部提炼按时间倒序汇集；点击任意一份展开阅读，或单独导出 Markdown。</p></section>${groups.map(([type,label])=>{const list=entries.filter(e=>e.type===type);if(!list.length)return '';return `<section class="recap-group"><div class="section-head"><h2>${label}提炼</h2><span>${list.length} 份</span></div><div class="record-list">${list.map(e=>`<details class="recap-item"${e.type==='digest'&&e.key===today?' open':''}><summary><span class="recap-title">${esc(e.title)}</span><span class="recap-count">${e.item.recordCount?`${e.item.recordCount} 段记录`:''}</span></summary><div class="digest-text">${esc(e.item.text)}</div><div class="recap-actions"><small>${e.item.model==='fallback'?'本地降级生成':esc(e.item.model||'')}</small><button type="button" class="text-btn export-btn" data-recap-export="${e.type}:${esc(e.key)}">${icon('download')}导出这一份</button></div></details>`).join('')}</div></section>`}).join('')}`;
}
function exportDigest(kind){if(kind==='digest'){const d=(appState.digests||{})[today];if(!d)return;download(`声迹今日提炼-${iso2cn(today)}.md`,`# 今日提炼 ${iso2cn(today)}\n\n${d.text}\n`,'text/markdown')}else if(kind==='weekly'){const ws=weekStart(today),we=weekEnd(today),w=(appState.weeklies||{})[ws];if(!w)return;download(`声迹周报-${iso2cn(w.start||ws)}至${iso2cn(w.end||we)}.md`,`# 本周提炼 ${iso2cn(w.start||ws)}至${iso2cn(w.end||we)}\n\n${w.text}\n`,'text/markdown')}else if(kind==='monthly'){const m=monthISO(),mo=(appState.monthlies||{})[m];if(!mo)return;download(`声迹月报-${iso2cn(m)}.md`,`# 本月提炼 ${iso2cn(m)}\n\n${mo.text}\n`,'text/markdown')}else if(kind==='yearly'){const y=today.slice(0,4),yr=(appState.yearlies||{})[y];if(!yr)return;download(`声迹年报-${y}年.md`,`# 年度回顾 ${y}年\n\n${yr.text}\n`,'text/markdown')}}
function actionSection(){const done=appState.doneActions||[],rows=[];records.filter(r=>r.value==='gem').forEach(r=>r.actions.forEach(text=>{const hit=done.find(a=>a.recordId===r.id&&a.text===text);rows.push({recordId:r.id,text,title:r.title,done:!!hit,at:hit?.at||''})}));if(!rows.length)return '<p class="action-empty">标记干货后，行动会集中在这里等勾。</p>';const open=rows.filter(x=>!x.done);return `<div class="section-head"><h2>接下来 · 干货行动清单</h2><span>${open.length} 条待办</span></div><div class="action-list">${open.map(actionRow).join('')}${rows.filter(x=>x.done).map(actionRow).join('')}</div>`}
const actionRow=x=>`<div class="action-row ${x.done?'done':''}"><button type="button" class="action-check" data-action-toggle="1" data-record-id="${esc(x.recordId)}" data-action-text="${esc(x.text)}" aria-label="${x.done?'恢复待办':'标记完成'}"></button><div class="action-copy"><span class="action-text">${esc(x.text)}</span>${x.done?`<small>${x.at?`${Number(x.at.slice(5,7))}月${Number(x.at.slice(8))}日 完成`:'已完成'}</small>`:`<small>来自「${esc(x.title)}」</small>`}</div></div>`;
